public class MainActivity extends Activity {
    static final int BG=0xff101918, CARD=0xff1b2826, SOFT=0xff263733, INK=0xfff2f5ea, MUTED=0xffaabbb1, LIME=0xffdbfa91;
    static final String[] NAMES={"精疲力尽","有些低落","阴天时刻","有点疲惫","平平淡淡","刚刚好","渐渐放晴","心情不错","满心欢喜","闪闪发光","无比美好"};
    FrameLayout root, stage; LinearLayout shell, nav, content; TextView[] tabs=new TextView[3], choices=new TextView[11];
    TextView moodTitle,moodCaption,saveButton,noteButton,latest; OrbView orb; EditText noteInput;
    int page=0,selected=-1; String note=""; boolean saving=false,loading=false,hasMore=true; long cursorTime=Long.MAX_VALUE,cursorId=Long.MAX_VALUE;
    Store store; final ExecutorService io=Executors.newSingleThreadExecutor(); final ArrayList<Record> history=new ArrayList<>(); HistoryAdapter adapter; ListView list; int generation=0; boolean alive=true;
    final Handler handler=new Handler(Looper.getMainLooper()); ArrayList<Record> week=new ArrayList<>(); long chartEnd; Celebration celebration;
    int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);} 
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);store=new Store(this);if(state!=null){selected=state.getInt("score",-1);note=state.getString("note","");page=state.getInt("page",0);}build();loadSummary();}
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putInt("score",selected);out.putString("note",note);out.putInt("page",page);}
    @Override protected void onDestroy(){alive=false;handler.removeCallbacksAndMessages(null);if(celebration!=null)celebration.stop();io.shutdown();super.onDestroy();}
    void ui(Runnable r){handler.post(()->{if(alive)r.run();});}
    GradientDrawable shape(int color,int radius){GradientDrawable b=new GradientDrawable();b.setColor(color);b.setCornerRadius(dp(radius));return b;}
    void ripple(View v,int color,int radius){v.setBackground(new RippleDrawable(ColorStateList.valueOf(0x33ffffff),shape(color,radius),shape(0xffffffff,radius)));}
    TextView text(String s,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setFontFeatureSettings("kern");v.setIncludeFontPadding(false);if(bold)v.setTypeface(android.graphics.Typeface.create("sans-serif-medium",0));return v;}
    LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w<0?w:dp(w),h<0?h:dp(h));}
    void gap(LinearLayout l,int h){l.addView(new View(this),lp(1,h));}
    TextView button(String label,int color,int fg){TextView b=text(label,15,fg,true);b.setGravity(Gravity.CENTER);b.setMinHeight(dp(54));b.setPadding(dp(12),dp(14),dp(12),dp(14));ripple(b,color,18);b.setClickable(true);press(b);return b;}
    void press(View v){v.setOnTouchListener((w,e)->{if(!w.isEnabled())return false;int a=e.getActionMasked();if(a==MotionEvent.ACTION_DOWN)w.animate().scaleX(.97f).scaleY(.97f).setDuration(100).start();else if(a==MotionEvent.ACTION_UP||a==MotionEvent.ACTION_CANCEL)w.animate().scaleX(1).scaleY(1).setDuration(220).setInterpolator(new OvershootInterpolator(1.3f)).start();return false;});}
    void build(){root=new FrameLayout(this);root.setBackgroundColor(BG);shell=column();root.addView(shell,new FrameLayout.LayoutParams(-1,-1));stage=new FrameLayout(this);shell.addView(stage,new LinearLayout.LayoutParams(-1,0,1));nav=new LinearLayout(this);nav.setPadding(dp(12),dp(8),dp(12),dp(8));nav.setBackgroundColor(CARD);shell.addView(nav,lp(-1,76));String[] labels={"◉  此刻","⌁  看板","☷  设置"};for(int i=0;i<3;i++){final int index=i;tabs[i]=button(labels[i],CARD,MUTED);nav.addView(tabs[i],new LinearLayout.LayoutParams(0,-1,1));tabs[i].setOnClickListener(v->{if(page!=index&&!saving){page=index;showPage(true);}});}setContentView(root);showPage(false);}
    void showPage(boolean animate){generation++;stage.removeAllViews();if(page==0)home();else if(page==1)dashboard();else settings();for(int i=0;i<3;i++){tabs[i].setTextColor(page==i?LIME:MUTED);ripple(tabs[i],page==i?SOFT:CARD,18);tabs[i].setSelected(page==i);}if(animate&&ValueAnimator.areAnimatorsEnabled()){View v=stage.getChildAt(0);v.setAlpha(0);v.setTranslationY(dp(12));v.animate().alpha(1).translationY(0).setDuration(300).setInterpolator(new DecelerateInterpolator()).start();}}
    LinearLayout scrollPage(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setClipToPadding(false);scroll.setVerticalScrollBarEnabled(false);content=column();content.setPadding(dp(24),dp(26),dp(24),dp(26));scroll.addView(content,new ScrollView.LayoutParams(-1,-2));stage.addView(scroll,new FrameLayout.LayoutParams(-1,-1));return content;}
    void heading(LinearLayout l,String eyebrow,String title,String subtitle){TextView tag=text(eyebrow,11,LIME,true);tag.setLetterSpacing(.16f);l.addView(tag);gap(l,14);l.addView(text(title,30,INK,true));gap(l,8);TextView sub=text(subtitle,13,MUTED,false);sub.setLineSpacing(dp(3),1);l.addView(sub);gap(l,24);}
    void home(){LinearLayout l=scrollPage();heading(l,"MOODLIGHT / 此刻","给心情，一点空间。","不必总是晴天，每一种感受都值得被记下。");
        LinearLayout hero=column();hero.setGravity(Gravity.CENTER);hero.setPadding(dp(16),dp(14),dp(16),dp(20));hero.setBackground(shape(CARD,28));l.addView(hero,lp(-1,-2));orb=new OrbView(this);hero.addView(orb,lp(-1,138));moodTitle=text(selected<0?"此刻的你，感觉如何？":NAMES[selected],22,INK,true);hero.addView(moodTitle);gap(hero,8);moodCaption=text(selected<0?"轻点一个分数，与自己打个照面":selected+" / 10  ·  每一分，都是真实的你",12,MUTED,false);hero.addView(moodCaption);gap(hero,22);
        for(int row=0;row<2;row++){LinearLayout line=new LinearLayout(this);line.setGravity(Gravity.CENTER);hero.addView(line,lp(-1,50));int count=row==0?6:5;for(int col=0;col<count;col++){final int score=row*6+col;TextView b=button(String.valueOf(score),selected==score?LIME:SOFT,selected==score?BG:INK);b.setPadding(0,0,0,0);b.setMinHeight(0);b.setTextSize(17);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(0,dp(44),1);params.setMargins(dp(3),dp(3),dp(3),dp(3));line.addView(b,params);choices[score]=b;b.setContentDescription(score+" 分，"+NAMES[score]);b.setOnClickListener(v->select(score));}}
        gap(hero,8);LinearLayout scale=new LinearLayout(this);TextView low=text("0 · 很低落",10,MUTED,false),high=text("很美好 · 10",10,MUTED,false);high.setGravity(Gravity.END);scale.addView(low,new LinearLayout.LayoutParams(0,-2,1));scale.addView(high,new LinearLayout.LayoutParams(0,-2,1));hero.addView(scale,lp(-1,-2));gap(l,16);
        noteButton=button(note.isEmpty()?"＋  添加一点理由  ·  可选":"✎  "+note,CARD,MUTED);noteButton.setGravity(Gravity.CENTER_VERTICAL);noteButton.setMaxLines(2);noteButton.setEllipsize(TextUtils.TruncateAt.END);l.addView(noteButton,lp(-1,-2));noteButton.setOnClickListener(v->editNote());gap(l,14);saveButton=button(selected<0?"先选择一个心情分数":"收好这一刻  ↗",selected<0?SOFT:LIME,selected<0?MUTED:BG);saveButton.setEnabled(selected>=0);l.addView(saveButton,lp(-1,-2));saveButton.setOnClickListener(v->save());gap(l,22);latest=text("仅保存在你的设备上。慢慢来，不着急。",12,MUTED,false);latest.setGravity(Gravity.CENTER);l.addView(latest);if(selected>=0)orb.score=selected;loadSummary();}
    void select(int score){if(saving)return;int old=selected;selected=score;performHaptic();for(int i=0;i<11;i++){ripple(choices[i],i==score?color(score):SOFT,14);choices[i].setTextColor(i==score?BG:INK);choices[i].setSelected(i==score);}choices[score].animate().scaleX(1.09f).scaleY(1.09f).setDuration(140).withEndAction(()->choices[score].animate().scaleX(1).scaleY(1).setDuration(240).setInterpolator(new OvershootInterpolator()).start()).start();moodTitle.setText(NAMES[score]);moodCaption.setText(score+" / 10  ·  每一分，都是真实的你");moodTitle.setAlpha(.4f);moodTitle.animate().alpha(1).setDuration(220).start();orb.change(score);ripple(saveButton,color(score),18);saveButton.setTextColor(BG);saveButton.setText("收好这一刻  ↗");saveButton.setEnabled(true);}
    void performHaptic(){root.performHapticFeedback(HapticFeedbackConstants.CLOCK_TICK);}
    void editNote(){Dialog dialog=new Dialog(this);LinearLayout box=column();box.setPadding(dp(24),dp(24),dp(24),dp(24));box.setBackground(shape(CARD,26));box.addView(text("留下一点理由",20,INK,true));gap(box,10);box.addView(text("随手写下几句，也可以留白。",13,MUTED,false));gap(box,18);EditText input=new EditText(this);noteInput=input;input.setTextColor(INK);input.setHintTextColor(MUTED);input.setTextSize(16);input.setHint("比如：晚风很好，刚好有人陪我散步。");input.setText(note);input.setGravity(Gravity.TOP);input.setPadding(dp(16),dp(16),dp(16),dp(16));input.setBackground(shape(SOFT,16));input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(2000)});box.addView(input,lp(-1,144));gap(box,18);TextView done=button("完成",LIME,BG);LinearLayout sheet=column();sheet.setBackground(shape(CARD,26));ScrollView form=new ScrollView(this);form.setFillViewport(false);form.addView(box);sheet.addView(form,new LinearLayout.LayoutParams(-1,0,1));LinearLayout.LayoutParams doneParams=lp(-1,-2);doneParams.setMargins(dp(24),dp(8),dp(24),dp(16));sheet.addView(done,0,doneParams);dialog.setContentView(sheet);Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));w.setLayout(-1,-2);w.setGravity(Gravity.BOTTOM);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}done.setOnClickListener(v->{note=input.getText().toString().trim();noteButton.setText(note.isEmpty()?"＋  添加一点理由  ·  可选":"✎  "+note);dialog.dismiss();});dialog.show();w.setLayout(-1,dp(380));w.getDecorView().getViewTreeObserver().addOnGlobalLayoutListener(()->{android.graphics.Rect visible=new android.graphics.Rect();w.getDecorView().getWindowVisibleDisplayFrame(visible);int target=Math.min(dp(380),visible.height());if(target>0&&sheet.getLayoutParams().height!=target){android.view.ViewGroup.LayoutParams params=sheet.getLayoutParams();params.height=target;sheet.setLayoutParams(params);}});box.setTranslationY(dp(100));box.setAlpha(0);box.animate().translationY(0).alpha(1).setDuration(300).setInterpolator(new DecelerateInterpolator()).start();input.requestFocus();input.postDelayed(()->{if(dialog.isShowing())((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(input,InputMethodManager.SHOW_IMPLICIT);},250);}
    void save(){if(saving||selected<0)return;saving=true;int score=selected;String reason=note;saveButton.setEnabled(false);saveButton.setText("正在收好…");io.execute(()->{try{store.insert(System.currentTimeMillis(),score,reason);ui(()->{performHaptic();celebration=new Celebration(this,score,()->{root.removeView(celebration);celebration=null;saving=false;selected=-1;note="";showPage(false);latest.setText("已收好这一刻。谢谢你，照顾自己的感受。");});root.addView(celebration,new FrameLayout.LayoutParams(-1,-1));celebration.start();});}catch(Exception e){ui(()->{saving=false;saveButton.setEnabled(true);saveButton.setText("重试保存");toast("保存失败，请重试");});}});}
    void loadSummary(){io.execute(()->{try{chartEnd=System.currentTimeMillis();ArrayList<Record> data=store.week(chartEnd);ui(()->week=data);}catch(Exception ignored){}});}
    void dashboard(){history.clear();hasMore=true;loading=false;cursorTime=Long.MAX_VALUE;cursorId=Long.MAX_VALUE;list=new ListView(this);list.setBackgroundColor(BG);list.setDivider(null);list.setVerticalScrollBarEnabled(false);list.setSelector(new ColorDrawable(Color.TRANSPARENT));list.setClipToPadding(false);list.setPadding(dp(24),0,dp(24),dp(12));LinearLayout head=column();head.setPadding(0,dp(26),0,0);heading(head,"MOODLIGHT / 轨迹","心情有起伏，也有光。","看看最近七天，走过了怎样的心情风景。");LinearLayout card=column();card.setPadding(dp(20),dp(22),dp(20),dp(20));card.setBackground(shape(CARD,26));TextView stats=text("正在整理你的轨迹…",20,INK,true);card.addView(stats);gap(card,8);card.addView(text("最近 7 天  ·  按记录时间分布",12,MUTED,false));ChartView chart=new ChartView(this);card.addView(chart,lp(-1,165));head.addView(card);gap(head,28);head.addView(text("时刻档案",18,INK,true));gap(head,10);list.addHeaderView(head,null,false);TextView footer=text("向上滑动，回看更早的自己",12,MUTED,false);footer.setGravity(Gravity.CENTER);footer.setPadding(0,dp(24),0,dp(24));list.addFooterView(footer,null,false);adapter=new HistoryAdapter();list.setAdapter(adapter);stage.addView(list,new FrameLayout.LayoutParams(-1,-1));int gen=generation;io.execute(()->{long end=System.currentTimeMillis();ArrayList<Record> points=store.week(end);ui(()->{if(gen!=generation)return;chart.set(points,end);stats.setText(points.isEmpty()?"轨迹，从这一刻开始":"每一个起伏，都算数。");});});list.setOnScrollListener(new AbsListView.OnScrollListener(){public void onScrollStateChanged(AbsListView l,int s){}public void onScroll(AbsListView l,int first,int visible,int total){if(first+visible>=total-5)loadMore(gen,footer);}});loadMore(gen,footer);list.setOnItemClickListener((parent,v,position,id)->{int i=position-list.getHeaderViewsCount();if(i>=0&&i<history.size())detail(history.get(i));});}
    void loadMore(int gen,TextView footer){if(loading||!hasMore||page!=1)return;loading=true;long t=cursorTime,id=cursorId;io.execute(()->{ArrayList<Record> batch=store.page(t,id,40);ui(()->{if(gen!=generation)return;history.addAll(batch);hasMore=batch.size()==40;if(!batch.isEmpty()){Record last=batch.get(batch.size()-1);cursorTime=last.time;cursorId=last.id;}loading=false;adapter.notifyDataSetChanged();footer.setText(history.isEmpty()?"还没有记录。去「此刻」留下第一笔吧。":hasMore?"继续滑动，回看更早的自己":"已经到最初的那一刻了。");});});}
    void detail(Record r){Dialog dialog=new Dialog(this);LinearLayout box=column();box.setPadding(dp(24),dp(24),dp(24),dp(24));box.setBackground(shape(CARD,24));box.addView(text(r.score+" / 10 · "+NAMES[r.score],22,color(r.score),true));gap(box,12);box.addView(text(time(r.time),13,MUTED,false));gap(box,20);TextView body=text(r.note.isEmpty()?"没有理由，也值得被记录。":r.note,16,INK,false);body.setTextIsSelectable(true);ScrollView sc=new ScrollView(this);sc.addView(body);box.addView(sc,lp(-1,180));gap(box,18);TextView close=button("收起",SOFT,INK);box.addView(close);close.setOnClickListener(v->dialog.dismiss());dialog.setContentView(box);dialog.getWindow().setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));dialog.show();dialog.getWindow().setLayout(getResources().getDisplayMetrics().widthPixels-dp(40),-2);}
    class HistoryAdapter extends BaseAdapter {public int getCount(){return history.size();}public Object getItem(int i){return history.get(i);}public long getItemId(int i){return history.get(i).id;}public boolean hasStableIds(){return true;}public View getView(int i,View old,android.view.ViewGroup parent){LinearLayout row;TextView badge,title,sub;if(old==null){row=new LinearLayout(MainActivity.this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(6),dp(16),dp(6),dp(16));badge=text("",20,BG,true);badge.setGravity(Gravity.CENTER);row.addView(badge,lp(48,48));LinearLayout words=column();LinearLayout.LayoutParams wp=new LinearLayout.LayoutParams(0,-2,1);wp.setMargins(dp(16),0,0,0);row.addView(words,wp);title=text("",14,INK,true);sub=text("",13,MUTED,false);sub.setMaxLines(2);sub.setEllipsize(TextUtils.TruncateAt.END);words.addView(title);gap(words,6);words.addView(sub);row.setTag(new TextView[]{badge,title,sub});ripple(row,BG,16);}else row=(LinearLayout)old;TextView[] h=(TextView[])row.getTag();Record r=history.get(i);h[0].setText(""+r.score);h[0].setBackground(shape(color(r.score),16));h[1].setText(time(r.time));h[2].setText(r.note.isEmpty()?NAMES[r.score]+" · 没有理由，也没关系":r.note);return row;}}
    void settings(){LinearLayout l=scrollPage();heading(l,"MOODLIGHT / 偏好","你的心事，由你保管。","没有账户，没有云端。只有你和你的记录。");LinearLayout card=column();card.setPadding(dp(22),dp(24),dp(22),dp(24));card.setBackground(shape(CARD,26));card.addView(text("记录与备份",22,INK,true));gap(card,12);card.addView(text("把心情装进一个 JSON 文件。换设备时，也能带上一路走来的自己。",14,MUTED,false));gap(card,24);TextView export=button("↗  导出记录",LIME,BG);card.addView(export,lp(-1,-2));gap(card,12);TextView imp=button("↙  导入记录",SOFT,INK);card.addView(imp,lp(-1,-2));export.setOnClickListener(v->{Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.setType("application/json");intent.putExtra(Intent.EXTRA_TITLE,"moodlight-"+new SimpleDateFormat("yyyyMMdd",Locale.ROOT).format(new Date())+".json");startActivityForResult(intent,10);});imp.setOnClickListener(v->{Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("*/*");intent.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,11);});gap(card,16);card.addView(text("导入会合并记录，重复的时刻会自动跳过。",12,MUTED,false));l.addView(card);gap(l,32);l.addView(text("小小记录，慢慢了解自己。",17,INK,true));gap(l,10);l.addView(text("MOODLIGHT  /  1.1\n你的每一种天气，都值得温柔以待。",12,MUTED,false));}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;android.net.Uri uri=data.getData();toast(request==10?"正在导出…":"正在读取…");io.execute(()->{try{if(request==10){try(OutputStream out=getContentResolver().openOutputStream(uri);Writer w=new OutputStreamWriter(out,java.nio.charset.StandardCharsets.UTF_8)){store.export(w);}ui(()->toast("导出成功"));}else{StringBuilder b=new StringBuilder();try(Reader reader=new InputStreamReader(getContentResolver().openInputStream(uri),java.nio.charset.StandardCharsets.UTF_8)){char[] buf=new char[4096];int n;while((n=reader.read(buf))!=-1){b.append(buf,0,n);if(b.length()>20_000_000)throw new IOException("文件过大（上限 20 MB）");}}int count=store.importJson(b.toString());ui(()->{toast("已导入 "+count+" 条新记录");showPage(true);});}}catch(Exception e){ui(()->toast("未完成："+(e.getMessage()==null?"请检查文件格式":e.getMessage())));}});}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    static int color(int score){return score<=3?0xffb8c8ff:score<=6?0xffa2e6d8:score<=8?LIME:0xffffd698;}
    static String time(long t){return new SimpleDateFormat("M月d日  ·  HH:mm",Locale.CHINA).format(new Date(t));}
}

class Record {long id,time;int score;float chartScore;String note;Record(long i,long t,int s,String n){id=i;time=t;score=s;chartScore=s;note=n;}}
class Store extends SQLiteOpenHelper {
    Store(Context c){super(c,"moments.db",null,1);SQLiteDatabase db=getWritableDatabase();if(!c.getSharedPreferences("migration",0).getBoolean("done",false)){String old=c.getSharedPreferences("MainActivity",0).getString("data","[]");try{importJson(old);c.getSharedPreferences("migration",0).edit().putBoolean("done",true).apply();}catch(Exception ignored){}}}
    public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE entries (id INTEGER PRIMARY KEY,time INTEGER NOT NULL,score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 10),note TEXT NOT NULL,UNIQUE(time,score,note))");db.execSQL("CREATE INDEX chronology ON entries(time DESC,id DESC)");}
    public void onUpgrade(SQLiteDatabase db,int old,int next){}
    void insert(long t,int s,String n){ContentValues v=new ContentValues();v.put("time",t);v.put("score",s);v.put("note",n);getWritableDatabase().insertOrThrow("entries",null,v);}
    ArrayList<Record> page(long time,long id,int limit){ArrayList<Record> out=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT id,time,score,note FROM entries WHERE time<? OR (time=? AND id<?) ORDER BY time DESC,id DESC LIMIT ?",new String[]{""+time,""+time,""+id,""+limit})){while(c.moveToNext())out.add(new Record(c.getLong(0),c.getLong(1),c.getInt(2),c.getString(3)));}return out;}
    ArrayList<Record> week(long end){ArrayList<Record> out=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT 0, (time/3600000)*3600000, AVG(score),'' FROM entries WHERE time>=? AND time<=? GROUP BY time/3600000 ORDER BY time ASC",new String[]{""+(end-7*86400000L),""+end})){while(c.moveToNext()){Record r=new Record(0,c.getLong(1),Math.round(c.getFloat(2)),"");r.chartScore=c.getFloat(2);out.add(r);}}return out;}
    void export(Writer w)throws Exception{w.write("{\"version\":1,\"records\":[");try(Cursor c=getReadableDatabase().rawQuery("SELECT time,score,note FROM entries ORDER BY time DESC,id DESC",null)){boolean first=true;while(c.moveToNext()){if(!first)w.write(",");first=false;JSONObject o=new JSONObject();o.put("time",c.getLong(0));o.put("score",c.getInt(1));o.put("note",c.getString(2));w.write(o.toString());}}w.write("]}");}
    int importJson(String s)throws Exception{Object root=new JSONTokener(s).nextValue();JSONArray data=root instanceof JSONArray?(JSONArray)root:((JSONObject)root).getJSONArray("records");SQLiteDatabase db=getWritableDatabase();db.beginTransaction();int added=0;try{for(int i=0;i<data.length();i++){JSONObject o=data.getJSONObject(i);long time=o.getLong("time");int score=o.getInt("score");String note=o.optString("note","");if(score<0||score>10||time<0||time>System.currentTimeMillis()+86400000L||note.length()>2000)throw new JSONException("第 "+(i+1)+" 条记录无效");ContentValues v=new ContentValues();v.put("time",time);v.put("score",score);v.put("note",note);if(db.insertWithOnConflict("entries",null,v,SQLiteDatabase.CONFLICT_IGNORE)!=-1)added++;}db.setTransactionSuccessful();}finally{db.endTransaction();}return added;}
}

class OrbView extends View {
    Paint p=new Paint(3);int score=5;float progress=1;ValueAnimator animator;
    OrbView(Context c){super(c);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}
    void change(int s){score=s;if(animator!=null)animator.cancel();animator=ValueAnimator.ofFloat(0,1);animator.setDuration(650);animator.setInterpolator(new OvershootInterpolator(1.2f));animator.addUpdateListener(a->{progress=(float)a.getAnimatedValue();invalidate();});animator.start();}
    protected void onDetachedFromWindow(){if(animator!=null)animator.cancel();super.onDetachedFromWindow();}
    protected void onDraw(Canvas c){float cx=getWidth()/2f,cy=getHeight()/2f,r=getHeight()*.31f;int col=MainActivity.color(score);c.save();float scale=.8f+.2f*progress;c.scale(scale,scale,cx,cy);p.setStyle(Paint.Style.FILL);p.setShader(new RadialGradient(cx,cy,r*1.65f,new int[]{col&0x00ffffff|0x44000000,Color.TRANSPARENT},null,Shader.TileMode.CLAMP));c.drawCircle(cx,cy,r*1.65f,p);p.setShader(new LinearGradient(cx-r,cy-r,cx+r,cy+r,new int[]{0xfff5ffe1,col},null,Shader.TileMode.CLAMP));c.drawCircle(cx,cy,r,p);p.setShader(null);p.setColor(0xff263a38);c.drawCircle(cx-r*.28f,cy-r*.12f,r*.065f,p);c.drawCircle(cx+r*.28f,cy-r*.12f,r*.065f,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(r*.055f);p.setStrokeCap(Paint.Cap.ROUND);Path mouth=new Path();mouth.moveTo(cx-r*.23f,cy+r*.24f);mouth.quadTo(cx,cy+r*(score<=3?.03f:score<=6?.28f:.55f),cx+r*.23f,cy+r*.24f);c.drawPath(mouth,p);p.setColor(col);p.setStrokeWidth(r*.02f);c.drawArc(cx-r*1.35f,cy-r*1.2f,cx+r*1.35f,cy+r*1.2f,200+progress*20,90,false,p);c.restore();}
}
class ChartView extends View {
    Paint p=new Paint(3);Path path=new Path();Path fill=new Path();ArrayList<Record> data=new ArrayList<>();long end;float reveal=1;ValueAnimator animation;
    ChartView(Context c){super(c);setContentDescription("最近七天心情走势，横向按小时分布");}
    void set(ArrayList<Record> d,long e){data=d;end=e;build();animation=ValueAnimator.ofFloat(0,1);animation.setDuration(800);animation.setInterpolator(new DecelerateInterpolator());animation.addUpdateListener(a->{reveal=(float)a.getAnimatedValue();invalidate();});animation.start();}
    protected void onSizeChanged(int w,int h,int ow,int oh){build();}
    float x(Record r){return 10+Math.max(0,Math.min(1,(r.time-(end-7*86400000L))/(float)(7*86400000L)))*(getWidth()-20);}
    float y(Record r){return getHeight()*.82f-r.chartScore/10f*getHeight()*.62f;}
    void build(){path.reset();fill.reset();for(int i=0;i<data.size();i++){Record r=data.get(i);if(i==0)path.moveTo(x(r),y(r));else{Record prev=data.get(i-1);float mid=(x(prev)+x(r))/2;path.cubicTo(mid,y(prev),mid,y(r),x(r),y(r));}}fill.set(path);if(!data.isEmpty()){fill.lineTo(x(data.get(data.size()-1)),getHeight()*.9f);fill.lineTo(x(data.get(0)),getHeight()*.9f);fill.close();}}
    protected void onDraw(Canvas c){if(data.isEmpty()){p.setColor(MainActivity.MUTED);p.setTextSize(getResources().getDisplayMetrics().scaledDensity*13);p.setTextAlign(Paint.Align.CENTER);c.drawText("下一次记录，从这里开始",getWidth()/2f,getHeight()/2f,p);return;}c.save();c.clipRect(0,0,getWidth()*reveal,getHeight());p.setStyle(Paint.Style.FILL);p.setShader(new LinearGradient(0,0,0,getHeight(),0x55dbfa91,0x00dbfa91,Shader.TileMode.CLAMP));c.drawPath(fill,p);p.setShader(null);p.setColor(MainActivity.LIME);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(getResources().getDisplayMetrics().density*2.5f);p.setStrokeCap(Paint.Cap.ROUND);c.drawPath(path,p);p.setStyle(Paint.Style.FILL);for(int i=0;i<data.size();i++){Record r=data.get(i);if(data.size()<=24||i==data.size()-1)c.drawCircle(x(r),y(r),getResources().getDisplayMetrics().density*3,p);}c.restore();}
    protected void onDetachedFromWindow(){if(animation!=null)animation.cancel();super.onDetachedFromWindow();}
}
class Celebration extends View {
    final int score,col;final Runnable done;final Paint p=new Paint(3);final Path path=new Path();final float[] angles=new float[60],speeds=new float[60];float t;ValueAnimator anim;
    Celebration(Context c,int score,Runnable done){super(c);this.score=score;this.col=MainActivity.color(score);this.done=done;setClickable(true);setContentDescription("已保存心情");Random r=new Random(24);for(int i=0;i<angles.length;i++){angles[i]=r.nextFloat()*6.283f;speeds[i]=.3f+r.nextFloat()*.7f;}}
    void start(){anim=ValueAnimator.ofFloat(0,1);anim.setDuration(ValueAnimator.areAnimatorsEnabled()?2100:400);anim.setInterpolator(new LinearInterpolator());anim.addUpdateListener(a->{t=(float)a.getAnimatedValue();invalidate();});anim.addListener(new AnimatorListenerAdapter(){boolean cancelled;public void onAnimationCancel(Animator a){cancelled=true;}public void onAnimationEnd(Animator a){if(!cancelled)done.run();}});anim.start();}
    void stop(){if(anim!=null)anim.cancel();}
    protected void onDetachedFromWindow(){stop();super.onDetachedFromWindow();}
    protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),cx=w/2,cy=h*.43f;float alpha=Math.min(1,t*8)*Math.min(1,(1-t)*6);p.setStyle(Paint.Style.FILL);p.setColor(Color.argb((int)(248*alpha),16,25,24));c.drawRect(0,0,w,h,p);p.setColor(col);p.setAlpha((int)(70*alpha));
        if(score<=3){for(int k=0;k<5;k++){path.reset();path.moveTo(0,h*.35f+k*h*.07f);for(int x=0;x<=w;x+=8){float yy=(float)Math.sin(x/w*5+t*4+k*.6)*h*.045f+h*.35f+k*h*.07f;path.lineTo(x,yy);}p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(h*.025f);p.setAlpha((int)((35+k*8)*alpha));c.drawPath(path,p);}}else if(score<=6){p.setStyle(Paint.Style.STROKE);for(int k=0;k<5;k++){p.setAlpha((int)(90*alpha*(1-k*.13f)));p.setStrokeWidth(2+k);c.drawCircle(cx,cy,w*(.07f+t*.5f+k*.15f),p);}}else{for(int i=0;i<angles.length;i++){float distance=w*(.06f+t*speeds[i]*.9f);float x=cx+(float)Math.cos(angles[i])*distance,y=cy+(float)Math.sin(angles[i])*distance+t*t*h*.12f;p.setStyle(Paint.Style.FILL);p.setColor(i%3==0?0xfff4f9ed:col);p.setAlpha((int)(200*alpha));c.save();c.rotate(t*180+i*12,x,y);if(score>=9)c.drawRoundRect(x-4,y-12,x+4,y+12,2,2,p);else c.drawCircle(x,y,3+speeds[i]*7,p);c.restore();}}
        p.setStyle(Paint.Style.FILL);p.setColor(col);p.setAlpha((int)(alpha*255));float r=w*.12f*(.75f+.25f*Math.min(1,t*5));c.drawCircle(cx,cy,r,p);p.setColor(MainActivity.BG);p.setAlpha((int)(alpha*255));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(w*.008f);p.setStrokeCap(Paint.Cap.ROUND);path.reset();path.moveTo(cx-r*.34f,cy);path.lineTo(cx-r*.05f,cy+r*.25f);path.lineTo(cx+r*.4f,cy-r*.28f);c.drawPath(path,p);p.setStyle(Paint.Style.FILL);p.setColor(MainActivity.INK);p.setAlpha((int)(alpha*255));p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.create("sans-serif-medium",0));p.setTextSize(w*.06f);c.drawText(score<=3?"阴天，也被温柔收好了。":score<=6?"把这一刻，轻轻收好。":"让这份快乐，多停留一会。",cx,cy+r+w*.13f,p);p.setTextSize(w*.033f);p.setColor(MainActivity.MUTED);p.setAlpha((int)(alpha*255));c.drawText("已保存  ·  "+score+" / 10",cx,cy+r+w*.22f,p);
    }
}
